// Where prototypes live, for the `software-factory prototype` command
// (command.ts) and for prototype mode in Kobble (mode.ts): each in its own
// copy of the project's code, a git worktree next to the project in
// `<project>-prototypes/`, so the owner's folder, its branch and its data
// are never touched. A card's prototype is on the branch
// `factory/issue-<number>`; a version of an idea on `factory/<idea>/<key>`.
// What running one means is the project's own: the company file's
// `prototype` commands, run in the copy, which tell them which copy it is
// in FACTORY_* variables.
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { readCompany, Workspace } from "@software-factory/core";
import { GIT } from "@software-factory/knowledge-base";
import { Refused } from "../refused.js";
// The line a start command prints to say where the running prototype is:
// `FACTORY_URL=http://localhost:5301`. The last one counts.
const URL_LINE = /^FACTORY_URL=(https?:\/\/\S+)\s*$/;
export function urlIn(line) {
    return URL_LINE.exec(line.trim())?.[1] ?? null;
}
// The copies live next to the project, in `<project>-prototypes/`.
export function homeOf(project) {
    return join(dirname(project), `${basename(project)}-prototypes`);
}
export function cardCopy(project, number) {
    const branch = `factory/issue-${String(number)}`;
    const folder = join(homeOf(project), `issue-${String(number)}`);
    return {
        name: `card #${String(number)}`,
        branch,
        folder,
        env: { FACTORY_CARD: String(number), ...envOf(project, branch, folder) },
    };
}
// The branch of a new version: `factory/<idea>/<key>`, the key in small
// letters (`factory/wish/b`).
export function versionBranch(idea, key) {
    return `factory/${idea}/${key.toLowerCase()}`;
}
// A version's copy, in `<project>-prototypes/<idea>/<key>`, on its branch.
export function versionCopy(project, idea, key, branch = versionBranch(idea, key)) {
    if (!/^[A-Za-z0-9][\w-]*$/.test(idea))
        throw new Refused(`“${idea}” cannot name an idea's prototypes.`);
    if (!/^[A-Za-z][A-Za-z0-9-]*$/.test(key))
        throw new Refused(`“${key}” cannot name a version.`);
    const folder = join(homeOf(project), idea, key.toLowerCase());
    return {
        name: `version ${key} of “${idea}”`,
        branch,
        folder,
        env: {
            FACTORY_IDEA: idea,
            FACTORY_VERSION: key,
            ...envOf(project, branch, folder),
        },
    };
}
function envOf(project, branch, folder) {
    return {
        FACTORY_BRANCH: branch,
        FACTORY_PROJECT: project,
        FACTORY_COPY: folder,
    };
}
// A version's copy as a working copy (core's Workspace): made when it is not
// there yet, on the version's branch (this computer's, else the one a
// teammate pushed to origin), or a new branch from the latest main.
export async function versionWorkspace(project, copy) {
    const workspace = new Workspace({
        source: project,
        workspaces: dirname(copy.folder),
        baseBranch: mainBranch(project),
    }, basename(copy.folder));
    if (existsSync(copy.folder))
        return workspace;
    try {
        await workspace.prepareLocalBranch(copy.branch);
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw new Refused(`The copy of ${copy.name} could not be made: ${message}`);
    }
    return workspace;
}
export function companyOf(root) {
    const read = readCompany(join(root, "factory.json"));
    if ("problem" in read)
        throw new Refused(read.problem);
    return read.company;
}
// The project's main branch: what origin calls its head, otherwise main.
export function mainBranch(project) {
    try {
        return git(project, ["symbolic-ref", "--short", "refs/remotes/origin/HEAD"])
            .trim()
            .replace(/^origin\//, "");
    }
    catch {
        return "main";
    }
}
export function git(cwd, args) {
    const result = spawnSync(GIT, args, { cwd, encoding: "utf8" });
    if (result.error)
        throw result.error;
    if (result.status !== 0)
        throw new Refused(`git ${args.slice(0, 2).join(" ")} failed: ${(result.stderr || result.stdout).trim()}`);
    return result.stdout;
}
// One word for a shell, so an option with spaces or quotes stays one option.
export function shellWord(word) {
    return `'${word.replaceAll("'", "'\\''")}'`;
}
// The words a project's command is said with, for the person.
export const NO_START = 'Nothing starts in it: name the project\'s start command in factory.json ("prototype": { "start": "…" }).';
